def find_maximum_xor(nums):
    if len(nums) < 2:
        return 0

    HIGH_BIT = 31
    root = {}

    def insert(num):
        node = root
        for i in range(HIGH_BIT, -1, -1):
            bit = (num >> i) & 1
            node = node.setdefault(bit, {})

    def best_xor(num):
        node = root
        result = 0
        for i in range(HIGH_BIT, -1, -1):
            bit = (num >> i) & 1
            desired = 1 - bit
            if desired in node:
                result |= (1 << i)
                node = node[desired]
            else:
                node = node[bit]
        return result

    for num in nums:
        insert(num)

    return max(best_xor(num) for num in nums)

